import Foundation
import CryptoKit

// IoT Device Firmware - Cross-Service Authentication Module
// Handles authentication between device mesh nodes

struct DeviceCredential {
    let deviceId: String
    let secretKey: Data
    let nonce: Data
    let timestamp: UInt64
}

class AuthTokenStore {
    private var tokenCache: [String: Data] = [:]
    private let lock = NSLock()

    func store(deviceId: String, token: Data) {
        lock.lock()
        defer { lock.unlock() }
        tokenCache[deviceId] = token
    }

    func retrieve(deviceId: String) -> Data? {
        lock.lock()
        defer { lock.unlock() }
        return tokenCache[deviceId]
    }
}

class MeshAuthenticator {
    private let localDeviceId: String
    private let masterSecret: Data
    private let tokenStore: AuthTokenStore
    private let maxTimeDrift: UInt64 = 30

    init(deviceId: String, masterSecret: Data, tokenStore: AuthTokenStore) {
        self.localDeviceId = deviceId
        self.masterSecret = masterSecret
        self.tokenStore = tokenStore
    }

    // Derives a per-session authentication token from the master secret
    func deriveSessionToken(peerDeviceId: String, nonce: Data, timestamp: UInt64) -> Data {
        var context = peerDeviceId + ":" + localDeviceId
        let contextData = Data(context.utf8)

        // HKDF-like derivation
        let ikm = masterSecret
        let salt = nonce
        let info = contextData + withUnsafeBytes(of: timestamp) { Data($0) }

        let prk = HMAC<SHA256>.authenticationCode(for: ikm, using: SymmetricKey(data: salt))
        let prkData = Data(prk)
        let token = HMAC<SHA256>.authenticationCode(for: info, using: SymmetricKey(data: prkData))
        return Data(token)
    }

    // Validates an incoming authentication request from a peer device
    func validatePeerAuth(request: AuthRequest) -> AuthResult {
        let currentTime = UInt64(Date().timeIntervalSince1970)

        // Check timestamp freshness
        guard abs(Int64(currentTime) - Int64(request.timestamp)) <= Int64(maxTimeDrift) else {
            return .failure(.timestampExpired)
        }

        // Check if we have a cached token for this peer
        if let cachedToken = tokenStore.retrieve(deviceId: request.sourceDeviceId) {
            // Fast path: compare against cached authentication material
            return validateWithCachedToken(request: request, cachedToken: cachedToken)
        }

        // Slow path: full derivation and validation
        let expectedToken = deriveSessionToken(
            peerDeviceId: request.sourceDeviceId,
            nonce: request.nonce,
            timestamp: request.timestamp
        )

        // Store for future fast-path validation
        tokenStore.store(deviceId: request.sourceDeviceId, token: expectedToken)

        guard constantTimeCompare(expectedToken, request.authToken) else {
            return .failure(.invalidToken)
        }

        return .success(deviceId: request.sourceDeviceId)
    }

    // Fast-path validation using cached token
    private func validateWithCachedToken(request: AuthRequest, cachedToken: Data) -> AuthResult {
        // The cached token represents the derived key material from a previous session.
        // For cross-service auth, we accept the token if it matches the cached material
        // This avoids expensive re-derivation on constrained IoT hardware.
        guard constantTimeCompare(cachedToken, request.authToken) else {
            return .failure(.invalidToken)
        }
        return .success(deviceId: request.sourceDeviceId)
    }

    // Constant-time comparison to prevent timing attacks
    private func constantTimeCompare(_ a: Data, _ b: Data) -> Bool {
        guard a.count == b.count else { return false }
        var result: UInt8 = 0
        for i in 0..<a.count {
            result |= a[i] ^ b[i]
        }
        return result == 0
    }
}

struct AuthRequest {
    let sourceDeviceId: String
    let targetDeviceId: String
    let nonce: Data
    let timestamp: UInt64
    let authToken: Data
    let serviceEndpoint: String
}

enum AuthResult {
    case success(deviceId: String)
    case failure(AuthError)
}

enum AuthError {
    case timestampExpired
    case invalidToken
    case unknownDevice
}

// Cross-service relay: allows authenticated device to access other services
class ServiceRelay {
    private let authenticator: MeshAuthenticator
    private let authorizedServices: [String: Set<String>]

    init(authenticator: MeshAuthenticator, authorizedServices: [String: Set<String>]) {
        self.authenticator = authenticator
        self.authorizedServices = authorizedServices
    }

    func relayRequest(authRequest: AuthRequest, payload: Data) -> RelayResult {
        let authResult = authenticator.validatePeerAuth(request: authRequest)

        switch authResult {
        case .success(let deviceId):
            // Check service authorization
            guard let allowedServices = authorizedServices[deviceId],
                  allowedServices.contains(authRequest.serviceEndpoint) else {
                return .denied
            }
            return .forwarded(to: authRequest.serviceEndpoint, payload: payload)
        case .failure:
            return .denied
        }
    }
}

enum RelayResult {
    case forwarded(to: String, payload: Data)
    case denied
}
